import{_ as o,a0 as p,w as r,s as i,ao as l,I as u,x as e,a1 as s,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"每日Ubuntu小技巧－讓鼠標適合左利手用户 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧－讓鼠標適合左利手用户 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧－讓鼠標適合左利手用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧－讓鼠標適合左利手用户 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Daily Ubuntu Tips–Make The Mouse Left-handed For Left Hand Users","title":"每日Ubuntu小技巧－讓鼠標適合左利手用户","tag":"201312","desc":""},"relativePath":"201312/Daily Ubuntu Tips–Make The Mouse Left-handed For Left Hand Users.md","filePath":"[post].md"}'),d={name:"201312/Daily Ubuntu Tips–Make The Mouse Left-handed For Left Hand Users.md"};function f(m,t,T,g,b,h){const n=p("Link");return r(),i("div",null,[t[11]||(t[11]=l('<h1 id="每日ubuntu小技巧-讓鼠標適合左利手用户" tabindex="-1">每日Ubuntu小技巧－讓鼠標適合左利手用户 <a class="header-anchor" href="#每日ubuntu小技巧-讓鼠標適合左利手用户" aria-label="Permalink to “每日Ubuntu小技巧－讓鼠標適合左利手用户”">​</a></h1><p>電腦的鼠標被設計成使用食指（大拇指旁邊的那個手指）完成大部分操作。默認情況下鼠標為右利手用户配置。打開電腦時，多數情況下你會使用食指完成點擊動作。</p><p>事實上，許多左利手用户（俗稱左撇子）習慣把鼠標放到鍵盤的左邊，然後用中指進行單擊操作。但這並不是左利手用户使用鼠標最好的方法。</p><p>這個簡短的教程為想要正確地使用左手操作鼠標的用户而編寫。它將會幫助左利手用户將鼠標設置成用食指點擊鼠標主鍵的操作模式。</p><p>這個教程同樣適用於右利手用户。如果鼠標為左利手用户設置，那麼右利手用户可以使用這個教程將鼠標鍵切換回來。</p><p>好了，現在咱們開始吧，點擊頂部右端面板中的齒輪按鈕選擇<strong>System Settings（系統設置）</strong>...</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/mouse-left-handed.png" alt=""></p><p>然後在系統設置選項中選擇<strong>Mouse &amp; Touchpad (鼠標和觸摸板)</strong>，打開後選擇‘<strong>Right(右)</strong>’選項，這樣就可以改變鼠標的主鍵以適應左利手用户。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/mouse-left-handed-1.png" alt=""></p><p>改回左以適應右利手用户。改變將會在選擇後立即生效。</p><p>就是這樣了。現在左撇子用户可以將鼠標移到鍵盤左邊，用左手的食指來正確地操作鼠標了。</p><p>使用愉快！</p><hr>',13)),u("p",null,[t[1]||(t[1]=e("via: ",-1)),s(n,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tipsmake-the-mouse-left-handed-for-left-hand-users/"},{default:a(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/11/daily-ubuntu-tipsmake-the-mouse-left-handed-for-left-hand-users/",-1)])]),_:1})]),u("p",null,[t[4]||(t[4]=e("譯者：",-1)),s(n,{href:"https://github.com/Linchenguang"},{default:a(()=>[...t[2]||(t[2]=[e("Linchenguang",-1)])]),_:1}),t[5]||(t[5]=e(" 校對：",-1)),s(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[e("wxy",-1)])]),_:1})]),u("p",null,[t[8]||(t[8]=e("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[e("LCTT",-1)])]),_:1}),t[9]||(t[9]=e(" 原創翻譯，",-1)),s(n,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[e("Linux中國",-1)])]),_:1}),t[10]||(t[10]=e(" 榮譽推出",-1))])])}const _=o(d,[["render",f]]);export{C as __pageData,_ as default};
